style.css:
@-moz-document domain("open.spotify.com") {
/* GENERAL BACKGROUND FIXES */
  body, html,
  .Root__main-view, .main-view-container,
  .main-home, .main-nowPlayingView-nowPlayingView,
  .main-nowPlayingBar-container {
    background-color: #111 !important;
    color: #e19dcd !important;
  }

  /* SIDEBARS */
  .Root__nav-bar,
  .main-yourLibraryX-nav,
  .os-host, .os-viewport {
    background-color: #1a1a1a !important;
  }

  /* PLAYLIST BIG PLAY BUTTON FIX */
  button[aria-label="Play"],
  button[aria-label="Pause"] {
    background-color: #e19dcd !important;
    color: black !important;
    fill: black !important;
    border: none !important;
  }

  button[aria-label="Play"]:hover,
  button[aria-label="Pause"]:hover {
    background-color: #f2c3e6 !important;
  }

  /* CURRENT SONG TITLE FIX */
  .main-nowPlayingWidget-title,
  .main-nowPlayingWidget-title a,
  .main-nowPlayingWidget-subtitle {
    color: #e19dcd !important;
  }

  /* REMOVE GREEN FROM ACTIVE/PLAYING SONG IN LIST */
  .main-trackList-trackListRow.main-trackList-active {
    background-color: #1a1a1a !important;
  }

  .main-trackList-trackListRow.main-trackList-active .main-trackList-rowTitle,
  .main-trackList-trackListRow.main-trackList-active .main-trackList-rowTitle a {
    color: #e19dcd !important;
  }

  /* REMOVE GREEN FROM ANY PLAYING STATE ICONS */
  .icon-play, .icon-play-active, svg[fill="#1fdf64"], [aria-label="Now playing"] {
    fill: #e19dcd !important;
    color: #e19dcd !important;
  }

  /* FIX "NOW PLAYING" MV BUTTON ICON */
  button[aria-label="Now playing"],
  button[aria-label="Now playing"]:hover {
    fill: #e19dcd !important;
    color: #e19dcd !important;
    background-color: transparent !important;
  }

  /* SVG OVERRIDE JUST IN CASE */
  svg {
    stroke: #e19dcd !important;
    fill: #e19dcd !important;
  }

  /* PROGRESS BAR */
  .playback-progressbar__fg {
    background-color: #e19dcd !important;
  }

  .playback-progressbar__bg {
    background-color: #333 !important;
  }

  /* SEARCH INPUT FIX */
  input,
  .x-searchInput-searchInput {
    background-color: #1a1a1a !important;
    color: #e19dcd !important;
    border: 1px solid #e19dcd44 !important;
  }

  input:focus {
    outline: 2px solid #e19dcd !important;
  }

  /* REMOVE GREEN TOOLTIP & TEXT COLORS */
  .encore-dark-theme .Type__color-brightAccent,
  .encore-dark-theme .Type__color-green,
  .Type__color-brightAccent,
  .Type__color-green {
    color: #e19dcd !important;
    fill: #e19dcd !important;
  }

  /* SCROLLBAR */
  ::-webkit-scrollbar-thumb {
    background-color: #e19dcd !important;
  }

  ::-webkit-scrollbar-track {
    background-color: #111 !important;
  }
}
